const LAB_HTML="<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#080c17\">\n<meta name=\"description\" content=\"Run real read-only Shards-MCP protocol checks, inspect public tools and resolve DNS using the live gateway.\">\n<title>Live Lab — Shards MCP</title>\n<style>\n:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#080c17;color:#e7f5fb}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 85% 0%,#143b5266,transparent 45%),radial-gradient(ellipse at 0 70%,#242a5260,transparent 42%),#080c17}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.55;cursor:wait}.shell{width:min(1180px,100%);margin:0 auto;padding:20px 22px 50px}header{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;padding:8px 0 25px;border-bottom:1px solid #314258}.brand{font-size:14px;font-weight:800;letter-spacing:.14em}.brand b{color:#8be7dc}.links{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.links a{border:1px solid #395365;border-radius:9px;padding:10px 13px;color:#c2dce9;font-size:12px}.links a:hover{border-color:#72d1ce;text-decoration:none}.eyebrow{font-size:11px;letter-spacing:.22em;color:#8be7dc;font-weight:750;text-transform:uppercase}h1{font-size:clamp(40px,7vw,77px);letter-spacing:-.069em;line-height:1.04;margin:16px 0 19px;max-width:820px}h1 em{font-style:normal;color:#91e6db}.lead{max-width:720px;color:#acc0d2;font-size:15px;line-height:1.8}.hero{padding:47px 0 34px}.statusbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:25px}.state{font:700 11px ui-monospace,monospace;padding:11px 13px;border:1px solid #396272;border-radius:9px;color:#a4d3db;background:#0d2736}.state.good{color:#a9f5db;border-color:#34846f}.state.bad{color:#ffbead;border-color:#99625f}.sub{font-size:11px;color:#829eb2}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.card,.output{background:linear-gradient(155deg,#122a3a,#0d182a 85%);border:1px solid #2e5063;border-radius:16px;padding:23px;min-width:0;box-shadow:0 16px 40px #0002}.num{font:700 11px ui-monospace,monospace;color:#89e3da;letter-spacing:.12em}h2{font-size:21px;letter-spacing:-.04em;margin:16px 0 10px}p{color:#a8becc;font-size:13px;line-height:1.8}.card button{margin-top:12px}.fieldrow{display:flex;gap:8px;margin:15px 0 2px}.field{background:#071524;border:1px solid #40596d;border-radius:8px;color:#d9f9f4;padding:12px 11px;min-width:0;width:100%;outline:none}.field:focus{border-color:#8ce2d8}select.field{width:97px}.btn{border:0;background:#9aeadd;color:#071824;border-radius:9px;padding:12px 16px;min-height:46px;font-size:12px;font-weight:820;letter-spacing:.035em}.btn:hover:not(:disabled){filter:brightness(1.08)}.btn.secondary{color:#cff8f4;background:#193d4e;border:1px solid #427080}.output{margin-top:16px}.outputtop{display:flex;align-items:center;justify-content:space-between;gap:13px;flex-wrap:wrap}.outputtop h2{margin:0}.outcome{font:700 12px ui-monospace,monospace;color:#91c8d1;min-height:26px;margin-top:17px}pre{white-space:pre-wrap;overflow-wrap:anywhere;color:#bce9dc;line-height:1.65;font:12px ui-monospace,monospace;border-radius:10px;background:#060f1c;border:1px solid #294456;padding:18px;margin:12px 0 0;min-height:130px;max-height:500px;overflow:auto}footer{padding:27px 0;margin-top:30px;border-top:1px solid #243c4d;color:#7e9aaa;font-size:11px;line-height:1.9}footer a{color:#9ae3dc}@media(max-width:860px){.grid{grid-template-columns:1fr}.hero{padding-top:38px}.card{padding:20px}.shell{padding:16px}.fieldrow{flex-wrap:wrap}.fieldrow .field:first-child{flex:1 1 180px}select.field{width:110px}.fieldrow button{flex:1 1 110px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n</style>\n</head>\n<body>\n<div class=\"shell\">\n<header><a class=\"brand\" href=\"/\">◇ SHARDS <b>/ MCP</b> <span style=\"color:#7995a8\">/ LAB</span></a><nav class=\"links\" aria-label=\"Navigation\"><a href=\"/\">Gateway</a><a href=\"/manage\">Operator console</a><a href=\"https://github.com/Shards-foundation/Shards-MCP\" target=\"_blank\" rel=\"noopener noreferrer\">Source</a></nav></header>\n<main>\n<section class=\"hero\"><div class=\"eyebrow\">Real HTTP requests · Public tools only</div><h1>Test the gateway.<br><em>See the evidence.</em></h1><p class=\"lead\">A live, browser-based MCP diagnostic surface. Every check calls the same hosted gateway used by external AI clients. Results come from responses, not fixtures. No sign-in or token required for these three public tools.</p><div class=\"statusbar\"><span id=\"endpointState\" class=\"state\" role=\"status\">Checking service…</span><span id=\"serviceDetail\" class=\"sub\">Target: mcp.shardsinc.co.uk/mcp</span></div></section>\n<div class=\"grid\">\n<section class=\"card\" aria-labelledby=\"protocolTitle\"><span class=\"num\">01 / CONNECTION DOCTOR</span><h2 id=\"protocolTitle\">Verify MCP transport</h2><p>Negotiate protocol, enumerate publicly discoverable tools, then invoke live gateway status. Shows the negotiated version and actual tool count.</p><button class=\"btn\" id=\"protocolRun\" type=\"button\">RUN PROTOCOL CHECK</button></section>\n<section class=\"card\" aria-labelledby=\"catalogTitle\"><span class=\"num\">02 / ECOSYSTEM DISCOVERY</span><h2 id=\"catalogTitle\">Inspect Shards services</h2><p>Call the public systems catalogue and inspect recorded project endpoints and development-stage labels. These are catalogue entries, not uptime claims.</p><button class=\"btn\" id=\"catalogRun\" type=\"button\">QUERY LIVE CATALOGUE</button></section>\n<section class=\"card\" aria-labelledby=\"dnsTitle\"><span class=\"num\">03 / DNS UTILITY</span><h2 id=\"dnsTitle\">Resolve a domain</h2><p>Query public A, AAAA, MX, TXT or CAA records using the gateway's existing passive Cloudflare DNS-over-HTTPS tool. No HTTP scanning.</p><form id=\"dnsForm\"><label for=\"domain\" class=\"sub\">Public domain</label><div class=\"fieldrow\"><input class=\"field\" id=\"domain\" name=\"domain\" placeholder=\"example.com\" value=\"example.com\" maxlength=\"253\" inputmode=\"url\" spellcheck=\"false\" required aria-label=\"Public domain\"><select class=\"field\" id=\"dnsType\" aria-label=\"DNS record type\"><option>A</option><option>AAAA</option><option>MX</option><option>TXT</option><option>CAA</option></select><button class=\"btn\" type=\"submit\">LOOK UP</button></div></form></section>\n</div>\n<section class=\"output\" aria-labelledby=\"outputTitle\"><div class=\"outputtop\"><h2 id=\"outputTitle\">Execution evidence</h2><button class=\"btn secondary\" id=\"copyEvidence\" type=\"button\" disabled>COPY JSON</button></div><div id=\"outcome\" class=\"outcome\" role=\"status\" aria-live=\"polite\">Choose a check to execute a real request.</div><pre id=\"response\" tabindex=\"0\" aria-label=\"JSON result\">No requests run yet.</pre><p class=\"sub\">Request failures, quota denials and protocol errors are displayed as errors. Results are not saved in this browser. Protected agent operations remain unavailable without separate operator-issued credentials.</p></section>\n</main>\n<footer>SHARDS FOUNDATION · EXPERIMENTAL EDGE · PUBLIC DIAGNOSTICS ONLY. <a href=\"/api/status\">Status endpoint</a> · <a href=\"https://github.com/Shards-foundation/Shards-MCP/blob/main/deployment/cloudflare/README.md\">Deployment boundaries</a></footer>\n</div><script src=\"/lab.js\" defer></script></body></html>";
const LAB_CLIENT="'use strict';\n(() => {\n  const $ = (id) => document.getElementById(id);\n  const buttons = [$('protocolRun'), $('catalogRun'), document.querySelector('#dnsForm button')];\n  const allowed = new Set(['shards_gateway_status', 'shards_systems_catalog', 'shards_dns_lookup']);\n  let evidence = null;\n  let seq = 0;\n  const report = (label, data) => {\n    evidence = {checked_at: new Date().toISOString(), label, ...data};\n    $('outcome').textContent = label;\n    $('response').textContent = JSON.stringify(evidence, null, 2);\n    $('copyEvidence').textContent = 'COPY JSON';\n    $('copyEvidence').disabled = false;\n  };\n  const busy = (state) => { for (const button of buttons) button.disabled = state; };\n  async function rpc(method, params = {}) {\n    const response = await fetch('/mcp', {\n      method: 'POST',\n      headers: {'content-type': 'application/json', 'accept': 'application/json, text/event-stream', 'mcp-protocol-version': '2025-11-25'},\n      credentials: 'omit',\n      cache: 'no-store',\n      redirect: 'error',\n      signal: AbortSignal.timeout(10000),\n      body: JSON.stringify({jsonrpc: '2.0', id: ++seq, method, params}),\n    });\n    const payload = await response.json().catch(() => { throw new Error('Gateway returned non-JSON data (HTTP ' + response.status + ')'); });\n    if (!response.ok) throw new Error('HTTP ' + response.status + ': ' + (payload.error?.message || payload.error || 'Gateway rejected request'));\n    if (payload.error) throw new Error('MCP ' + payload.error.code + ': ' + payload.error.message);\n    if (!payload.result || payload.jsonrpc !== '2.0') throw new Error('Malformed MCP JSON-RPC response');\n    if (payload.result.isError) throw new Error((payload.result.content || []).map(x => x.text || '').join('; ') || 'MCP tool failed');\n    return payload.result;\n  }\n  async function publicTool(name, args = {}) {\n    if (!allowed.has(name)) throw new Error('Not a supported public tool');\n    const result = await rpc('tools/call', {name, arguments: args});\n    if (result.structuredContent !== undefined) return result.structuredContent;\n    try { return JSON.parse(result.content?.[0]?.text || '{}'); }\n    catch { throw new Error('Tool returned an unexpected response format'); }\n  }\n  async function run(label, action) {\n    busy(true);\n    $('outcome').textContent = 'Executing ' + label + '…';\n    const start = performance.now();\n    try {\n      const result = await action();\n      report('PASS · ' + label, {elapsed_ms: Math.round(performance.now() - start), result});\n    } catch (error) {\n      report('FAIL · ' + label, {elapsed_ms: Math.round(performance.now() - start), error: String(error?.message || error)});\n    } finally {\n      busy(false);\n    }\n  }\n  $('protocolRun').addEventListener('click', () => run('Protocol and public status', async () => {\n    const init = await rpc('initialize', {protocolVersion: '2025-11-25', capabilities: {}, clientInfo: {name: 'shards-live-lab', version: '1.0'}});\n    const listing = await rpc('tools/list');\n    const status = await publicTool('shards_gateway_status');\n    return {negotiated_version: init.protocolVersion, server: init.serverInfo, listed_tools: (listing.tools || []).map(x => x.name), tool_count: (listing.tools || []).length, status};\n  }));\n  $('catalogRun').addEventListener('click', () => run('Ecosystem catalogue', () => publicTool('shards_systems_catalog')));\n  $('dnsForm').addEventListener('submit', (event) => {\n    event.preventDefault();\n    const domain = $('domain').value.trim().toLowerCase().replace(/\\.$/, '');\n    const type = $('dnsType').value;\n    if (!/^(?=.{4,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}$/.test(domain) || !['A','AAAA','MX','TXT','CAA'].includes(type)) {\n      report('FAIL · DNS lookup', {error: 'Enter a valid public domain and DNS record type.'});\n      return;\n    }\n    run('DNS ' + type + ' / ' + domain, () => publicTool('shards_dns_lookup', {domain, type}));\n  });\n  $('copyEvidence').addEventListener('click', async () => {\n    if (!evidence) return;\n    try { await navigator.clipboard.writeText(JSON.stringify(evidence, null, 2)); $('copyEvidence').textContent = 'COPIED'; }\n    catch { $('copyEvidence').textContent = 'COPY FAILED'; }\n    setTimeout(() => { $('copyEvidence').textContent = 'COPY JSON'; }, 1600);\n  });\n  fetch('/api/status', {credentials:'omit',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(7000)})\n    .then(async r => { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })\n    .then(data => {\n      const ok = data.db === 'connected';\n      $('endpointState').textContent = ok ? 'STATUS API / DATABASE CONNECTED' : 'STATUS API / DATABASE UNAVAILABLE';\n      $('endpointState').classList.add(ok ? 'good' : 'bad');\n      $('serviceDetail').textContent = (data.service || 'Shards MCP Edge') + ' · ' + (data.version || 'unknown version') + ' · ' + (data.tools?.length || 0) + ' advertised tools';\n    }).catch(error => { $('endpointState').textContent = 'STATUS API / UNREACHABLE'; $('endpointState').classList.add('bad'); $('serviceDetail').textContent = String(error.message || error); });\n})();";
const SIGNIN_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#070c16\"><title>Sign in | Shards MCP</title><meta name=\"description\" content=\"Authenticate to Shards MCP through verified identity providers.\"><style>:root{font-family:Inter,system-ui,-apple-system,sans-serif;color-scheme:dark;background:#070c16;color:#eff7fb}*{box-sizing:border-box}body{min-height:100vh;display:grid;place-items:center;padding:26px;margin:0;background:radial-gradient(circle at 80% -20%,#1c4765aa,transparent 60%),radial-gradient(circle at -20% 90%,#1e2d59bb,transparent 60%),#070c16}.wrap{max-width:480px;width:100%}.brand{display:block;color:#8ee8de;font-size:12px;letter-spacing:.2em;font-weight:800;text-decoration:none;margin-bottom:23px}.panel{background:linear-gradient(145deg,#13293a,#0d1626);border:1px solid #315065;border-radius:23px;padding:32px;box-shadow:0 28px 80px #0005}.eyebrow{font-size:11px;color:#8fe7dd;letter-spacing:.17em;text-transform:uppercase;font-weight:750}h1{font-size:clamp(34px,8vw,53px);letter-spacing:-.055em;line-height:1.05;margin:14px 0}p{color:#afc4d3;font-size:14px;line-height:1.8}.auth{display:flex;align-items:center;justify-content:center;gap:13px;width:100%;min-height:56px;margin:26px 0 12px;border-radius:13px;color:#07131d;background:linear-gradient(125deg,#99f0e5,#92c9fa);font-weight:800;text-decoration:none}.auth:hover{filter:brightness(1.09)}.logo{display:grid;place-items:center;width:25px;height:25px;border:2px solid currentColor;border-radius:8px}.details{border-top:1px solid #344c5b;padding-top:16px;margin-top:25px;color:#8faabb;font-size:12px;line-height:1.8}.details a{color:#a7e7e0}footer{margin-top:20px;color:#718b9e;font-size:11px;line-height:1.8}@media(max-width:500px){.panel{padding:24px}}</style></head><body><div class=\"wrap\"><a class=\"brand\" href=\"/\">◇ SHARDS / MCP</a><main class=\"panel\"><span class=\"eyebrow\">Secure authentication</span><h1>Connect your identity.</h1><p>Continue using a verified identity provider. Cloudflare Access handles the sign-in, session and consent process; Shards never receives your provider password.</p><a class=\"auth\" href=\"/connect/profile\"><span class=\"logo\">◇</span>Continue with Cloudflare Access</a><p style=\"font-size:12px\">On Cloudflare's secure screen, choose Cloudflare account or email one-time code when your identity is permitted by the Access policy. This signs you into the authenticated MCP connection. Access to internal agent tools still requires separate authorisation.</p><div class=\"details\">Additional providers will appear only when their OAuth integrations are operational. A valid login does not grant administrator privileges or access to other users' agents.<p><a href=\"/lab\">Try public tools without signing in</a></p></div></main><footer>Shards Foundation · Authentication uses Cloudflare Access · <a href=\"https://github.com/Shards-foundation/Shards-MCP\" style=\"color:#9dded7\">Open source</a></footer></div></body></html>";
const SIGNED_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#070c16\"><title>Connected identity | Shards MCP</title><style>:root{font-family:Inter,system-ui,sans-serif;color-scheme:dark;color:#e4f5f5;background:#080e19}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(ellipse at 70% 0%,#17445d,transparent 65%),#080e19}.card{width:min(520px,100%);background:#102638;border:1px solid #3b6a71;padding:28px;border-radius:20px}h1{letter-spacing:-.06em;font-size:38px}.ok{font-size:11px;letter-spacing:.17em;font-weight:800;color:#a5f5d4}p{font-size:14px;line-height:1.8;color:#a9c2d2}.row{background:#081724;border:1px solid #344c60;border-radius:9px;padding:12px;color:#c9f2eb;overflow-wrap:anywhere;font:12px ui-monospace,monospace}.label{font-size:11px;color:#8ba9bc;margin-top:18px;margin-bottom:6px}a{color:#9ce4d7}code{overflow-wrap:anywhere}</style></head><body><main class=\"card\"><div class=\"ok\">✓ VERIFIED IDENTITY</div><h1>You're signed in.</h1><p>Cloudflare Access has authenticated this browser session. Your identity was verified with the application-specific signed token, not a password collected by Shards.</p><div class=\"label\">Provider</div><div class=\"row\">Cloudflare Access</div><div class=\"label\">Authenticated identity</div><div class=\"row\" id=\"identity\">__IDENTITY__</div><div class=\"label\">Your MCP endpoint</div><div class=\"row\">https://mcp.shardsinc.co.uk/connect</div><p>This endpoint exposes only public discovery and your own verified session identity. Internal messaging, agent tasks and operator controls are not granted by social login.</p><p><a href=\"/lab\">Open public Live Lab</a> · <a href=\"/\">Gateway home</a></p></main></body></html>";
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function oauthIssuer(env){
  if(!env||typeof env.ACCESS_AUD!=='string'||!env.ACCESS_AUD.trim()||env.ACCESS_AUD!==env.ACCESS_AUD.trim()||typeof env.CONNECT_ACCESS_AUD!=='string'||!env.CONNECT_ACCESS_AUD.trim()||env.CONNECT_ACCESS_AUD!==env.CONNECT_ACCESS_AUD.trim()||env.CONNECT_ACCESS_AUD===env.ACCESS_AUD||typeof env.ACCESS_TEAM!=='string'||!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(env.ACCESS_TEAM))return null;
  return 'https://'+env.ACCESS_TEAM+'.cloudflareaccess.com';
}
const WORKSPACE_HTML="<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#080e18\"><meta name=\"description\" content=\"Operator-only real-time agent messaging and task observation for the Shards-MCP gateway.\">\n<title>Workspace · Shards MCP</title>\n<style>\n:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;color-scheme:dark;background:#080e18;color:#e6f3f7}\n*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 78% -30%,#10445e80,transparent 55%),#080e18}button,textarea{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.42}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}h1,h2,h3,p{margin-top:0}.shell{max-width:1600px;margin:0 auto;padding:0 16px 24px}.top{height:auto;min-height:79px;display:flex;gap:14px;justify-content:space-between;align-items:center;flex-wrap:wrap;border-bottom:1px solid #203b4b;padding:17px 5px}.brand{font-weight:850;letter-spacing:.13em;font-size:13px;white-space:nowrap}.brand span{color:#84e4d9}.brand i{font-style:normal;color:#668ba0;font-weight:500}.menu{display:flex;align-items:center;flex-wrap:wrap;gap:8px}.link,.refresh{font-size:11px;font-weight:750;letter-spacing:.05em;min-height:37px;display:inline-flex;align-items:center;border-radius:9px;border:1px solid #315164;padding:10px 12px;color:#b6d5df;background:#102335}.link.active{background:#183e44;border-color:#4daaa3;color:#b8f7e8}.link:hover,.refresh:hover{border-color:#82dfd0;text-decoration:none}.pulse{height:7px;width:7px;background:#6adbb7;border-radius:99px;display:inline-block;margin-right:7px}.heading{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;padding:27px 3px 19px;flex-wrap:wrap}.eyebrow{font:750 10px ui-monospace,monospace;letter-spacing:.22em;text-transform:uppercase;color:#84dfd7}.heading h1{margin:10px 0 0;font-size:clamp(27px,4vw,42px);letter-spacing:-.056em;line-height:1.07}.heading p{font-size:12px;color:#8faebe;max-width:450px;line-height:1.7;margin:7px 0 0}.metrics{display:flex;gap:9px;flex-wrap:wrap}.metric{border:1px solid #2e4a5a;background:#101f2d;border-radius:11px;padding:10px 15px;min-width:90px}.metric strong{font:750 23px ui-monospace,monospace;letter-spacing:-.03em;display:block}.metric span{font:700 9px ui-monospace,monospace;letter-spacing:.08em;color:#84a5b7}.layout{display:grid;grid-template-columns:249px minmax(0,1fr) 286px;gap:13px;min-height:610px}.pane{background:linear-gradient(155deg,#101f30,#0a1423);border:1px solid #294455;border-radius:14px;min-width:0;overflow:hidden}.panehead{padding:21px 18px 13px;border-bottom:1px solid #1f3948}.panehead h2{font-size:13px;letter-spacing:.03em;margin:0 0 4px}.panehead p{margin:0;font-size:10px;line-height:1.5;color:#7f9bab}.agents{display:grid;gap:5px;padding:11px;align-content:start}.agent{width:100%;display:flex;gap:10px;align-items:center;text-align:left;background:transparent;color:#c8e0e6;border:1px solid transparent;border-radius:10px;padding:12px 9px;min-height:58px}.agent:hover{background:#172d40}.agent.active{border-color:#427c82;background:#18404a}.avatar{display:grid;place-items:center;flex:none;height:36px;width:36px;background:linear-gradient(130deg,#214d55,#1a3157);border:1px solid #456776;border-radius:11px;font-size:13px;color:#b5fff1;font-weight:800}.agentname{font-size:12px;font-weight:770;display:block}.agentmeta{color:#839fae;font-size:10px;margin-top:3px;display:block}.empty{padding:26px 20px;color:#9db7c4;font-size:12px;line-height:1.8}.empty a{color:#91e2d8;text-decoration:underline}.mainpane{display:flex;flex-direction:column;min-height:605px}.threadhead{padding:18px 23px;border-bottom:1px solid #263f52;display:flex;justify-content:space-between;gap:13px;align-items:center;flex-wrap:wrap}.threadhead h2{margin:0 0 4px;font-size:18px;letter-spacing:-.025em}.hint{font:10px ui-monospace,monospace;color:#829eae}.thread{min-height:280px;max-height:54vh;flex:1;overflow:auto;padding:20px 23px;display:flex;flex-direction:column;gap:16px}.bubble{max-width:86%;min-width:0;align-self:flex-start}.bubble.own{align-self:flex-end}.meta{font-size:10px;color:#8baabb;margin-bottom:6px;display:flex;justify-content:space-between;gap:14px}.msg{background:#182a3b;border:1px solid #345166;color:#d9edf1;padding:12px 14px;border-radius:12px 12px 12px 3px;font-size:13px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere}.own .msg{background:#164443;border-color:#367875;border-radius:12px 12px 3px 12px}.own .meta{color:#8bdcc9}.composer{border-top:1px solid #263f52;padding:16px 22px 18px}.composer label{display:block;color:#9ab6c4;font-size:10px;letter-spacing:.05em;margin-bottom:9px;font-weight:700}textarea{background:#091623;border:1px solid #3a5667;color:#e6f8f4;border-radius:10px;width:100%;min-height:82px;resize:vertical;padding:13px;outline:none;font-size:13px;line-height:1.6}textarea:focus{border-color:#89e0d5}.composefoot{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:10px;flex-wrap:wrap}.muted{color:#839eaf;font-size:10px;line-height:1.6}.send{background:#94e9dd;color:#072027;font-size:11px;font-weight:850;letter-spacing:.045em;padding:12px 18px;border:0;border-radius:9px;min-height:42px}.send:hover:not(:disabled){filter:brightness(1.09)}.tasks{padding:13px;display:grid;gap:9px}.task{border:1px solid #2e495a;border-radius:10px;padding:13px;background:#0c1d2d;min-width:0}.task h3{font-size:12px;margin:0 0 9px;overflow-wrap:anywhere}.task p{font-size:10px;color:#86a1b2;line-height:1.5;margin:8px 0 0}.state{font:750 9px ui-monospace,monospace;letter-spacing:.09em;padding:5px 7px;background:#324550;color:#d6e3ea;border-radius:7px}.state.queued{color:#f1d59a;background:#3a3021}.state.claimed{color:#a5d2f6;background:#233c50}.state.completed{color:#a7ebd0;background:#1e413e}.sectionline{padding:18px 18px 10px;border-top:1px solid #243e4e}.sectionline h3{font-size:12px;margin:0 0 7px}.sectionline p{font-size:11px;line-height:1.7;color:#8eabba;margin:0}.integrations{display:grid;gap:2px;padding:11px 15px 17px}.integration{display:flex;justify-content:space-between;gap:12px;padding:9px 0;font-size:11px;border-bottom:1px solid #1e3545}.integration span:last-child{color:#879eae;font-size:10px}.footer{font:10px ui-monospace,monospace;color:#7994a5;line-height:1.7;padding:14px 5px}.status{font:11px ui-monospace,monospace;color:#8cdbd0}.status.bad{color:#ffb2a9}@media(max-width:1150px){.layout{grid-template-columns:230px minmax(0,1fr)}.right{grid-column:1/-1}.right .tasks{grid-template-columns:repeat(auto-fill,minmax(210px,1fr))}.integrations{grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}}@media(max-width:680px){.shell{padding:0 9px 20px}.top{padding:13px 2px}.brand{font-size:11px}.heading{padding:24px 5px 15px}.metrics{width:100%}.metric{flex:1}.layout{grid-template-columns:minmax(0,1fr)}.agents{display:flex;overflow-x:auto;scrollbar-width:thin}.agent{flex:none;width:175px}.agentname{max-width:120px;overflow:hidden;text-overflow:ellipsis}.thread{max-height:46vh;min-height:270px}.mainpane{min-height:525px}.right{grid-column:1}.panehead{padding:17px}.threadhead,.composer{padding:16px}.bubble{max-width:93%}.integrations{grid-template-columns:1fr}}\n</style></head><body>\n<div class=\"shell\">\n<header class=\"top\"><a class=\"brand\" href=\"/\">◇ SHARDS <span>/ MCP</span> <i>/ WORKSPACE</i></a><nav class=\"menu\" aria-label=\"Main navigation\"><a class=\"link active\" href=\"/manage/workspace\">MESSAGES</a><a class=\"link\" href=\"/manage\">ENROL AGENTS</a><a class=\"link\" href=\"/lab\">LIVE LAB</a><button class=\"refresh\" id=\"refresh\" type=\"button\">↻ REFRESH</button></nav></header>\n<section class=\"heading\"><div><div class=\"eyebrow\"><span class=\"pulse\"></span> Operator-only collaboration console</div><h1>Agent workspace.</h1><p>Real conversations, actual task state and enrolled agents. This page never substitutes simulated replies for running AI agents.</p></div><div class=\"metrics\"><div class=\"metric\"><strong id=\"agentCount\">—</strong><span>ENROLLED AGENTS</span></div><div class=\"metric\"><strong id=\"messageCount\">—</strong><span>RECENT MESSAGES</span></div><div class=\"metric\"><strong id=\"taskCount\">—</strong><span>RECENT TASKS</span></div></div></section>\n<section class=\"layout\">\n<aside class=\"pane\"><div class=\"panehead\"><h2>Direct conversations</h2><p>Select an enrolled agent or <a href=\"/manage\" style=\"color:#90e3d9\">add a new one</a></p></div><nav id=\"agentList\" class=\"agents\" aria-label=\"Agent conversations\"><div class=\"empty\">Loading enrolled agents…</div></nav></aside>\n<section class=\"pane mainpane\" aria-labelledby=\"threadTitle\"><div class=\"threadhead\"><div><h2 id=\"threadTitle\">Choose an agent</h2><div class=\"hint\" id=\"threadSubtitle\">Authenticated operator • presence not tracked</div></div><span class=\"status\" id=\"status\" role=\"status\" aria-live=\"polite\">Connecting…</span></div><div id=\"thread\" class=\"thread\" aria-live=\"off\"><div class=\"empty\">Select an agent to view its real message history. No conversations have been simulated.</div></div><form id=\"composer\" class=\"composer\"><label id=\"recipientLabel\" for=\"message\">MESSAGE AN ENROLLED AGENT · RECORDED IN ITS MCP INBOX</label><textarea id=\"message\" rows=\"3\" maxlength=\"2000\" placeholder=\"Write a message to the selected agent…\" disabled required></textarea><div class=\"composefoot\"><div class=\"muted\">Stored ≠ read or executed. Agents must poll their inbox and respond from their own runtime.</div><button id=\"send\" class=\"send\" type=\"submit\" disabled>SEND MESSAGE</button></div></form></section>\n<aside class=\"pane right\"><div class=\"panehead\"><h2>Task activity</h2><p>Actual queued, claimed and completed records</p></div><div class=\"tasks\" id=\"taskList\"><div class=\"empty\">Select an agent to view tasks.</div></div><div class=\"sectionline\"><h3>External app connections</h3><p>Provider integrations require real OAuth/bot credentials, scopes and an active connector worker. None are implied by these labels.</p></div><div class=\"integrations\" aria-label=\"External provider status\"><div class=\"integration\"><span>Slack</span><span>Not connected</span></div><div class=\"integration\"><span>Discord</span><span>Not connected</span></div><div class=\"integration\"><span>Telegram</span><span>Not connected</span></div><div class=\"integration\"><span>WhatsApp</span><span>Not connected</span></div></div></aside>\n</section>\n<footer class=\"footer\">SHARDS FOUNDATION · AUTHENTICATED OPERATOR · EU D1 PERSISTENCE · POLLING (12 SEC) · NO INFERRED ONLINE STATUS · <a href=\"https://github.com/Shards-foundation/Shards-MCP\">SOURCE</a></footer>\n</div><script src=\"/manage/workspace.js\" defer></script></body></html>";
const WORKSPACE_CLIENT="'use strict';(()=>{\n const $=id=>document.getElementById(id);\n const state={snapshot:null,selected:null,sending:false,requestId:null,requestBody:null,loading:false};\n const dom=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e};\n const status=(message,bad=false)=>{$('status').textContent=message;$('status').classList.toggle('bad',bad)};\n const fmt=x=>{try{return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(x))}catch{return String(x)}};\n const activeAgents=()=>state.snapshot?state.snapshot.agents.filter(a=>a.client!=='operator-ui'):[];\n function renderAgents(){\n   const box=$('agentList');box.replaceChildren();\n   const agents=activeAgents();\n   $('agentCount').textContent=String(agents.length);\n   if(!agents.length){const e=dom('div','empty');e.append('No enrolled agent is available yet. ');const a=dom('a',null,'Open agent enrolment');a.href='/manage';e.append(a,'.');box.append(e);return}\n   for(const a of agents){\n     const b=dom('button','agent'+(a.id===state.selected?' active':''));b.type='button';b.setAttribute('aria-pressed',String(a.id===state.selected));\n     b.append(dom('span','avatar',a.name.slice(0,2).toUpperCase()));\n     const label=dom('span');label.append(dom('span','agentname',a.name),dom('span','agentmeta',a.client+' · enrolled, not verified online'));b.append(label);\n     b.addEventListener('click',()=>{if(state.selected===a.id)return;state.selected=a.id;state.requestId=null;state.requestBody=null;$('message').value='';render();status('Draft cleared when switching recipient');load(true);});\n     box.append(b);\n   }\n }\n function renderMessages(){\n   const selected=activeAgents().find(a=>a.id===state.selected);\n   const area=$('thread');area.replaceChildren();\n   $('threadTitle').textContent=selected?selected.name:'Choose an agent';\n   $('recipientLabel').textContent=selected?'TO '+selected.name.toUpperCase()+' · STORED IN ITS MCP INBOX':'SELECT AN AGENT BEFORE SENDING';\n   $('threadSubtitle').textContent=selected?selected.client+' · MCP inbox enabled · presence unknown':'Authenticated operator · presence not tracked';\n   $('message').disabled=!selected||state.sending;$('send').disabled=!selected||state.sending;\n   if(!selected){area.append(dom('div','empty','Select an enrolled agent to inspect actual messages and send an operator message.'));return}\n   if(state.snapshot.focus_id!==state.selected){area.append(dom('div','empty','Loading this agent’s message history…'));return}\n   const messages=(state.snapshot.messages||[]).filter(m=>m.sender_id===selected.id||m.recipient_id===selected.id).slice().reverse();\n   if(!messages.length){area.append(dom('div','empty','No messages recorded for this agent. You can send the first operator message below. It will appear in the agent’s real MCP inbox.'));return}\n   for(const m of messages){\n     const own=m.sender_id===state.snapshot.operator_id;\n     const item=dom('article','bubble'+(own?' own':''));\n     const info=dom('div','meta');\n     const from=own?'You · operator':m.sender_name||'Enrolled agent';\n     const to=m.recipient_name||'Enrolled agent';\n     info.append(dom('span',null,from+' → '+to),dom('time',null,fmt(m.created_at)));\n     const body=dom('div','msg',m.body);\n     item.append(info,body);area.append(item);\n   }\n }\n function renderTasks(){\n   const box=$('taskList');box.replaceChildren();\n   const tasks=(state.snapshot?.tasks||[]).filter(t=>t.assignee_id===state.selected||t.creator_id===state.selected);\n   if(!state.selected){box.append(dom('div','empty','Select an agent to inspect its actual task records.'));return}\n   if(state.snapshot.focus_id!==state.selected){box.append(dom('div','empty','Loading this agent’s task history…'));return}\n   if(!tasks.length){box.append(dom('div','empty','No tasks are recorded for this agent. Task execution is performed by external agents, not this website.'));return}\n   for(const t of tasks.slice(0,30)){\n     const el=dom('article','task'),heading=dom('h3',null,t.title),tag=dom('span','state '+t.state,t.state.toUpperCase());\n     el.append(heading,tag,dom('p',null,(t.assignee_name||'Agent')+' · '+fmt(t.created_at)));box.append(el);\n   }\n }\n function render(){\n   if(!state.snapshot)return;\n   $('messageCount').textContent=String(state.snapshot.messages.length);\n   $('taskCount').textContent=String(state.snapshot.tasks.length);\n   renderAgents();renderMessages();renderTasks();\n }\n async function load(showLoading=false){\n   if(state.loading)return;\n   state.loading=true;\n   if(showLoading)status('Loading real gateway data…');\n   try{\n     const endpoint='/manage/api/workspace'+(state.selected?'?agent_id='+encodeURIComponent(state.selected):'');\n     const res=await fetch(endpoint,{credentials:'same-origin',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(9000)});\n     if(!res.ok)throw Error('Workspace request denied (HTTP '+res.status+'). Check operator sign-in.');\n     const data=await res.json();\n     if(!Array.isArray(data.agents)||!Array.isArray(data.messages)||!Array.isArray(data.tasks)||typeof data.operator_id!=='string')throw Error('Unexpected workspace response');\n     state.snapshot=data;\n     const agents=activeAgents();\n     if(!agents.some(x=>x.id===state.selected))state.selected=data.focus_id||agents[0]?.id||null;\n     render();status('Synced '+new Date().toLocaleTimeString());\n   }catch(error){status(String(error.message||error),true);if(!state.snapshot){$('agentList').replaceChildren(dom('div','empty','Cannot load operator workspace. Sign in via Cloudflare Access and try again.'));}}\n   finally{state.loading=false}\n }\n $('refresh').addEventListener('click',()=>load(true));\n $('composer').addEventListener('submit',async event=>{\n   event.preventDefault();\n   if(state.sending||!state.selected)return;\n   const message=$('message').value.trim();\n   if(!message||message.length>2000)return;\n   state.sending=true;$('send').disabled=true;$('message').disabled=true;status('Storing message…');\n   const payloadSignature=state.selected+'|'+message;\n   if(!state.requestId||state.requestBody!==payloadSignature){state.requestId=crypto.randomUUID();state.requestBody=payloadSignature}\n   try{\n     const res=await fetch('/manage/api/workspace/messages',{method:'POST',credentials:'same-origin',redirect:'error',cache:'no-store',signal:AbortSignal.timeout(12000),headers:{'content-type':'application/json'},body:JSON.stringify({recipient_agent_id:state.selected,body:message,request_id:state.requestId})});\n     const data=await res.json().catch(()=>({}));\n     if(!res.ok||!data.stored)throw Error(data.error||'Message could not be stored (HTTP '+res.status+')');\n     $('message').value='';state.requestId=null;state.requestBody=null;\n     await load();\n     status(data.idempotent?'Message already stored · no duplicate created':'Message stored in agent inbox · awaiting agent poll');\n     $('thread').scrollTop=$('thread').scrollHeight;\n   }catch(error){status('Send not confirmed. Refresh history before retrying unchanged text. '+String(error.message||error),true)}\n   finally{state.sending=false;$('send').disabled=!state.selected;$('message').disabled=!state.selected}\n });\n load(true);\n setInterval(()=>{if(!document.hidden&&!state.sending)load(false)},12000);\n})();";
const SETTINGS_HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"theme-color\" content=\"#08111d\"><meta name=\"description\" content=\"Shards MCP authenticated operator account settings and security credentials\"><title>Account settings | Shards MCP</title>\n<style>\n:root{color-scheme:dark;--bg:#08111d;--panel:#0d1f2c;--panel2:#112a38;--border:#294656;--text:#e8f9f8;--muted:#97b4c0;--accent:#91eddf;--btn:#133840;--warn:#efaa84;--input:#081925;font:14px Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif}\n:root[data-theme=light]{color-scheme:light;--bg:#f0f6f8;--panel:#fff;--panel2:#ebf5f6;--border:#a0bcc9;--text:#142d38;--muted:#445b68;--accent:#075951;--btn:#e0f0ed;--warn:#843116;--input:#f6fafb}\n:root[data-theme=contrast]{color-scheme:dark;--bg:#000;--panel:#000;--panel2:#0b0b0b;--border:#fff;--text:#fff;--muted:#e2e2e2;--accent:#fff900;--btn:#151515;--warn:#ff8d8d;--input:#000}\n*{box-sizing:border-box}html{background:var(--bg)}body{margin:0;min-height:100vh;color:var(--text);background:radial-gradient(ellipse 60vw 25vw at 78% -15%,#0a51502a,transparent),var(--bg)}a{color:var(--accent)}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.4;cursor:not-allowed}input,select,textarea{color:var(--text);background:var(--input);border:1px solid var(--border);border-radius:9px;padding:12px;width:100%;outline-offset:2px}textarea{min-height:94px;resize:vertical}input:focus,select:focus,textarea:focus{outline:2px solid var(--accent)}input[type=file]{padding:8px}h1,h2,h3,p{margin-top:0}small,.hint{font-size:11px;color:var(--muted);line-height:1.7}.shell{max-width:1310px;padding:0 17px 60px;margin:auto}.top{padding:21px 2px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.brand{text-decoration:none;font-weight:850;font-size:12px;letter-spacing:.15em;color:var(--text)}.brand span{color:var(--accent)}.links{display:flex;flex-wrap:wrap;gap:9px}.links a{border:1px solid var(--border);border-radius:9px;padding:10px 12px;text-decoration:none;color:var(--muted);font-size:11px}.links a.active{color:var(--accent);background:var(--panel2)}.intro{padding:27px 2px 24px;display:flex;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;gap:15px}.eyebrow{text-transform:uppercase;font:750 10px ui-monospace,monospace;color:var(--accent);letter-spacing:.19em}.intro h1{font-size:clamp(30px,4.7vw,45px);letter-spacing:-.06em;margin:10px 0 6px}.intro p{margin:0;color:var(--muted);font-size:12px}.notice{font-size:11px;color:var(--accent);padding:9px 13px;background:var(--panel);border:1px solid var(--border);border-radius:9px;max-width:440px}.notice.bad{color:var(--warn)}.layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:18px}.tabs{align-self:start;position:sticky;top:15px;display:grid;gap:5px}.tab{width:100%;text-align:left;color:var(--muted);border:1px solid transparent;background:transparent;padding:14px 13px;border-radius:10px;font-weight:700;font-size:12px}.tab[aria-selected=true],.tab:hover{background:var(--panel2);color:var(--text);border-color:var(--border)}.tab.danger{color:var(--warn)}.content{min-width:0}.section{display:none}.section.active{display:block}.card{background:var(--panel);border:1px solid var(--border);border-radius:16px;padding:25px;margin-bottom:14px}.card h2{margin:0 0 7px;font-size:19px;letter-spacing:-.02em}.card h3{font-size:13px;margin:0 0 8px}.card>p{font-size:12px;color:var(--muted);line-height:1.8}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.field label{font-size:11px;font-weight:740;letter-spacing:.03em;display:block;margin-bottom:7px}.field.full{grid-column:1/-1}.field .hint{display:block;margin-top:7px}.btn{width:auto;background:var(--accent);color:var(--bg);padding:11px 17px;border:1px solid var(--accent);border-radius:9px;font-weight:850;font-size:11px;letter-spacing:.03em;min-height:41px}.btn.outline{background:var(--btn);color:var(--text);border-color:var(--border)}.btn.danger{background:#a6372b;color:white;border-color:#a6372b}.actions{margin-top:19px;display:flex;align-items:center;flex-wrap:wrap;gap:10px}.avatar-line{display:flex;align-items:center;gap:16px;margin:13px 0 20px}.avatar{height:72px;width:72px;display:grid;place-items:center;object-fit:cover;border-radius:20px;border:1px solid var(--border);background:var(--panel2);font-size:25px;color:var(--accent);font-weight:850}.avatar-line span{max-width:340px}.themegrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:13px}.theme{border:1px solid var(--border);background:var(--panel2);color:var(--text);border-radius:12px;padding:20px 8px;min-height:78px;font-weight:770;font-size:12px}.theme[aria-pressed=true]{outline:2px solid var(--accent)}.row{padding:16px 0;border-bottom:1px solid var(--border);display:flex;gap:12px;justify-content:space-between;align-items:center;flex-wrap:wrap}.row strong{font-size:12px}.row p{font-size:11px;color:var(--muted);margin:5px 0 0;line-height:1.65}.tag{font:700 10px ui-monospace,monospace;color:var(--accent);border:1px solid var(--border);padding:5px 8px;border-radius:7px}.tag.off{color:var(--muted)}.key{overflow-wrap:anywhere;word-break:break-word;padding:14px;border:1px solid var(--border);background:var(--input);border-radius:10px;font:12px ui-monospace,monospace;color:var(--accent)}.list{display:grid;gap:9px;margin-top:15px}.listitem{border:1px solid var(--border);border-radius:10px;padding:14px;display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.listitem h3{font-size:12px;margin-bottom:5px;overflow-wrap:anywhere}.listitem p{margin:0;color:var(--muted);font-size:10px;line-height:1.7;overflow-wrap:anywhere}.muted{color:var(--muted)}.divider{height:1px;background:var(--border);margin:19px 0}.warning{border:1px solid #b96c59;background:#54241d25;color:var(--text);border-radius:11px;padding:15px;font-size:12px;line-height:1.75}.footer{padding:25px 0;color:var(--muted);font:10px ui-monospace,monospace;line-height:1.8}\n@media(max-width:820px){.layout{grid-template-columns:1fr}.tabs{position:static;display:flex;overflow-x:auto;scrollbar-width:thin}.tab{flex:0 0 auto;min-width:115px;text-align:center}.card{padding:19px}.fields{grid-template-columns:1fr}.field.full{grid-column:1}.themegrid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:400px){.shell{padding:0 10px 35px}.card{padding:15px}.intro{padding:21px 0 18px}.avatar-line{align-items:flex-start}}\n</style></head><body><div class=\"shell\">\n<header class=\"top\"><a href=\"/\" class=\"brand\">◇ SHARDS <span>/ MCP</span> / ACCOUNT</a><div class=\"links\"><a href=\"/manage/workspace\">Workspace</a><a href=\"/manage\">Agent enrolment</a><a class=\"active\" href=\"/manage/settings\">Account settings</a></div></header>\n<div class=\"intro\"><div><div class=\"eyebrow\">Operator identity / security</div><h1>Account settings.</h1><p>Manage your profile, developer credentials and security records.</p></div><div id=\"notice\" class=\"notice\" role=\"status\" aria-live=\"polite\">Authenticating with Cloudflare Access…</div></div>\n<div class=\"layout\">\n<nav class=\"tabs\" role=\"tablist\" aria-label=\"Account settings\"><button type=\"button\" class=\"tab\" data-tab=\"profile\" aria-selected=\"true\">Profile</button><button type=\"button\" class=\"tab\" data-tab=\"appearance\" aria-selected=\"false\">Appearance</button><button type=\"button\" class=\"tab\" data-tab=\"security\" aria-selected=\"false\">Security</button><button type=\"button\" class=\"tab\" data-tab=\"credentials\" aria-selected=\"false\">API & CLI keys</button><button type=\"button\" class=\"tab\" data-tab=\"connections\" aria-selected=\"false\">Connections</button><button type=\"button\" class=\"tab\" data-tab=\"ssh\" aria-selected=\"false\">SSH keys</button><button type=\"button\" class=\"tab danger\" data-tab=\"delete\" aria-selected=\"false\">Delete account</button></nav>\n<main class=\"content\">\n<section class=\"section active\" data-section=\"profile\"><div class=\"card\"><h2>Personal profile</h2><p>Only identity claims from your signed Cloudflare Access session determine account ownership. The displayed email is not user-editable.</p><div class=\"avatar-line\"><img id=\"avatarImage\" class=\"avatar\" alt=\"Account avatar\" hidden><div id=\"avatarInitials\" class=\"avatar\" aria-hidden=\"true\">◇</div><span class=\"hint\">Upload your own small photo. It is resized locally and stored in Shards EU D1, not sent to another image host.</span></div><form id=\"profileForm\"><div class=\"fields\"><div class=\"field\"><label for=\"fullName\">Full name</label><input id=\"fullName\" maxlength=\"100\" autocomplete=\"name\" placeholder=\"Your display name\"></div><div class=\"field\"><label for=\"email\">Email address (identity provider)</label><input id=\"email\" type=\"email\" readonly><span class=\"hint\">Change your verified identity email with your provider; Shards cannot verify a new email independently.</span></div><div class=\"field full\"><label for=\"avatarFile\">Avatar (PNG, JPEG or WebP)</label><input id=\"avatarFile\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\"><span class=\"hint\">Resized to 96×96; maximum stored image 24 KB.</span></div></div><div class=\"actions\"><button class=\"btn\" type=\"submit\">SAVE PROFILE</button><button id=\"clearAvatar\" class=\"btn outline\" type=\"button\">REMOVE AVATAR</button></div></form></div></section>\n<section class=\"section\" data-section=\"appearance\"><div class=\"card\"><h2>Appearance</h2><p>Choose your dashboard theme. Settings persist in your signed account profile across devices.</p><div class=\"themegrid\" role=\"group\" aria-label=\"Theme\"><button type=\"button\" class=\"theme\" data-theme-choice=\"system\" aria-pressed=\"true\">System</button><button type=\"button\" class=\"theme\" data-theme-choice=\"dark\" aria-pressed=\"false\">Dark</button><button type=\"button\" class=\"theme\" data-theme-choice=\"light\" aria-pressed=\"false\">Light</button><button type=\"button\" class=\"theme\" data-theme-choice=\"contrast\" aria-pressed=\"false\">High contrast</button></div><div class=\"actions\"><button id=\"saveTheme\" class=\"btn\" type=\"button\">SAVE APPEARANCE</button></div></div></section>\n<section class=\"section\" data-section=\"security\"><div class=\"card\"><h2>Sign-in security</h2><p>Your Shards operator login is authenticated through Cloudflare Access. Shards does not store a password or issue MFA recovery codes.</p><div class=\"row\"><div><strong>Primary login</strong><p>Cloudflare Access · configured operator identity</p></div><span class=\"tag\">ACTIVE</span></div><div class=\"row\"><div><strong>Password</strong><p>Managed by your identity provider. A passwordless email-code login has no Shards password to change.</p></div><span class=\"tag off\">PROVIDER-MANAGED</span></div><div class=\"row\"><div><strong>Two-factor authentication</strong><p>Managed by Cloudflare Access and your identity provider. This site cannot independently verify or enable MFA.</p></div><span class=\"tag off\">UNVERIFIED HERE</span></div><div class=\"row\"><div><strong>Login methods & account linking</strong><p>Additional Google, GitHub, Discord, Apple, Microsoft, Meta, Claude and OpenAI provider registrations are not enabled by a button on this page.</p></div><span class=\"tag off\">ADMIN CONFIGURATION</span></div><div class=\"row\"><div><strong>Session protection</strong><p>Your provider enforces the operator Access session; API/CLI keys are separate and have no admin privileges.</p></div><span class=\"tag\">SIGNED JWT</span></div></div></section>\n<section class=\"section\" data-section=\"credentials\"><div class=\"card\"><h2>API keys & CLI tokens</h2><p>Create real, independently revocable credentials for the <code>GET /v1/account/whoami</code> account endpoint. These keys are <strong>read-only</strong> and cannot enrol agents, send messages, run tools or use SSH.</p><form id=\"keyForm\"><div class=\"fields\"><div class=\"field\"><label for=\"keyLabel\">Credential label</label><input id=\"keyLabel\" required maxlength=\"60\" placeholder=\"e.g. Android Termux\"></div><div class=\"field\"><label for=\"keyKind\">Credential type</label><select id=\"keyKind\"><option value=\"api\">API key</option><option value=\"cli\">CLI token</option></select></div><div class=\"field\"><label for=\"keyExpiry\">Expiration</label><select id=\"keyExpiry\"><option value=\"30\">30 days</option><option value=\"90\">90 days</option></select></div></div><div class=\"actions\"><button class=\"btn\" type=\"submit\">CREATE CREDENTIAL</button></div></form><div id=\"secretPanel\" hidden><div class=\"divider\"></div><h3>New credential — visible once</h3><p class=\"hint\">Copy this key now. Only its SHA-256 digest is stored; it cannot be recovered after leaving this page.</p><div id=\"secretOutput\" class=\"key\"></div><div class=\"actions\"><button id=\"copySecret\" class=\"btn\" type=\"button\">COPY KEY</button><button id=\"dismissSecret\" class=\"btn outline\" type=\"button\">DISMISS</button></div></div><div class=\"divider\"></div><h3>Issued credentials</h3><div id=\"keysList\" class=\"list\"><span class=\"hint\">Loading…</span></div></div></section>\n<section class=\"section\" data-section=\"connections\"><div class=\"card\"><h2>Live connections</h2><p>Lists actual issued agent credentials and recently used account keys. A credential being active does not prove that a device or AI runtime is online.</p><div id=\"connectionsList\" class=\"list\"><span class=\"hint\">Loading…</span></div><div class=\"divider\"></div><h3>External integrations</h3><div class=\"row\"><strong>Slack / Discord / Telegram / WhatsApp</strong><span class=\"tag off\">NOT CONNECTED HERE</span></div><p class=\"hint\">These are not advertised as connected until an independently verified adapter and permission grant exist.</p></div></section>\n<section class=\"section\" data-section=\"ssh\"><div class=\"card\"><h2>SSH public keys</h2><p>Register and remove OpenSSH Ed25519 <strong>public</strong> keys. Shards never accepts private keys here. Stored keys do not grant shell access until a separate authorised host integration exists.</p><form id=\"sshForm\"><div class=\"fields\"><div class=\"field full\"><label for=\"sshLabel\">Key label</label><input id=\"sshLabel\" maxlength=\"60\" required placeholder=\"e.g. Termux phone\"></div><div class=\"field full\"><label for=\"sshPublic\">Public key (ssh-ed25519)</label><textarea id=\"sshPublic\" required spellcheck=\"false\" placeholder=\"ssh-ed25519 AAAAC3...\"></textarea></div></div><div class=\"actions\"><button class=\"btn\" type=\"submit\">ADD PUBLIC KEY</button></div></form><div class=\"divider\"></div><h3>Saved SSH public keys</h3><div id=\"sshList\" class=\"list\"><span class=\"hint\">Loading…</span></div></div></section>\n<section class=\"section\" data-section=\"delete\"><div class=\"card\"><h2>Delete Shards account</h2><div class=\"warning\">This deletes your Shards-local profile and SSH-key records, revokes API/CLI credentials and disables the agent credentials you issued. Historical organisation messages and audit records are retained. Your external Cloudflare identity is <strong>not</strong> deleted.</div><form id=\"deleteForm\"><div class=\"field\" style=\"margin-top:19px\"><label for=\"deleteConfirm\">Type DELETE MY SHARDS ACCOUNT to confirm</label><input id=\"deleteConfirm\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"DELETE MY SHARDS ACCOUNT\" required></div><div class=\"actions\"><button type=\"submit\" class=\"btn danger\">DELETE SHARDS-LOCAL ACCOUNT</button></div></form></div></section>\n</main></div><footer class=\"footer\">SHARDS FOUNDATION · VERIFIED CLOUDFLARE ACCESS OPERATOR · PRIVACY-RESPECTING LOCAL CREDENTIAL MANAGEMENT · <a href=\"https://github.com/Shards-foundation/Shards-MCP\">SOURCE</a></footer>\n</div><script src=\"/manage/settings.js\" defer></script></body></html>";
const SETTINGS_CLIENT="'use strict';(()=>{\n const $=id=>document.getElementById(id),state={profile:null,avatar:null,theme:'system',loaded:false,deleted:false,busy:false},api='/manage/api/account';\n const note=(t,bad=false)=>{const n=$('notice');n.textContent=t;n.classList.toggle('bad',bad)};\n const call=async(path,method='GET',body=null)=>{const r=await fetch(path,{method,credentials:'same-origin',redirect:'error',cache:'no-store',signal:AbortSignal.timeout(12000),headers:body===null?{}:{'content-type':'application/json'},body:body===null?undefined:JSON.stringify(body)});let data;try{data=await r.json()}catch{throw Error('Expected JSON response. Verify your Cloudflare Access session.')}if(!r.ok)throw Error(data.error||('HTTP '+r.status));return data};\n const node=(tag,klass,text)=>{const n=document.createElement(tag);if(klass)n.className=klass;if(text!==undefined)n.textContent=text;return n};\n const action=(label,handler)=>{const b=node('button','btn outline',label);b.type='button';b.addEventListener('click',handler);return b};\n const stamp=t=>t?new Date(t).toLocaleString():'never';\n function theme(t){state.theme=t;document.documentElement.dataset.theme=t==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):t;for(const b of document.querySelectorAll('[data-theme-choice]'))b.setAttribute('aria-pressed',String(b.dataset.themeChoice===t))}\n function preview(){const n=$('avatarImage');if(state.avatar){n.src=state.avatar;n.hidden=false;$('avatarInitials').hidden=true}else{n.removeAttribute('src');n.hidden=true;$('avatarInitials').hidden=false;$('avatarInitials').textContent=($('fullName').value.trim().slice(0,2)||'◇').toUpperCase()}}\n const writeItem=(box,title,caption,buttons=[])=>{const row=node('div','listitem'),info=node('div');info.append(node('h3',null,title),node('p',null,caption));row.append(info);for(const b of buttons)row.append(b);box.append(row)};\n async function load(){\n  try{\n   const data=await call(api);\n   state.loaded=true;state.profile=data.profile;state.avatar=data.profile.avatar_data||null;theme(data.profile.theme||'system');\n   $('fullName').value=data.profile.full_name||'';$('email').value=data.profile.email||'';preview();\n   const keys=$('keysList');keys.replaceChildren();\n   if(!data.api_keys.length)keys.append(node('div','hint','No account credentials issued.'));\n   for(const k of data.api_keys){\n    const active=!k.revoked_at&&new Date(k.expires_at)>new Date();\n    const b=active?action('REVOKE',async()=>{if(!confirm('Revoke credential '+k.label+'?'))return;try{await call(api+'/keys/'+k.id,'DELETE',{});note('Credential revoked');await load()}catch(e){note(e.message,true)}}):null;\n    writeItem(keys,k.label+' · '+k.kind.toUpperCase(),k.prefix+'… · expires '+stamp(k.expires_at)+' · last used '+stamp(k.last_used_at)+' · '+(active?'active':'revoked or expired'),b?[b]:[]);\n   }\n   const ssh=$('sshList');ssh.replaceChildren();\n   if(!data.ssh_keys.length)ssh.append(node('div','hint','No SSH public keys registered.'));\n   for(const k of data.ssh_keys)writeItem(ssh,k.label,k.algorithm+' · '+k.fingerprint+' · '+stamp(k.created_at),[action('REMOVE',async()=>{if(!confirm('Remove SSH key '+k.label+'?'))return;try{await call(api+'/ssh/'+k.id,'DELETE',{});note('SSH key removed');await load()}catch(e){note(e.message,true)}})]);\n   const list=$('connectionsList');list.replaceChildren();\n   if(!data.connections.agents.length&&!data.api_keys.length)list.append(node('div','hint','No issued connections or active account credentials.'));\n   for(const a of data.connections.agents)writeItem(list,a.name+' · '+a.client,'Agent enrolment · '+(a.disabled_at?'disabled':'enrolled')+' · '+a.active_credentials+' active credential(s) · actual runtime online status unknown');\n   for(const k of data.api_keys.filter(x=>!x.revoked_at&&new Date(x.expires_at)>new Date()))writeItem(list,k.label+' · '+k.kind,'Account credential · '+(k.last_used_at?'last authenticated '+stamp(k.last_used_at):'never used')+' · online status unknown');\n   note('Account settings synchronised');\n  }catch(e){note(e.message,true);if(/deleted/i.test(e.message))state.deleted=true}\n }\n function tab(name){for(const b of document.querySelectorAll('[data-tab]'))b.setAttribute('aria-selected',String(b.dataset.tab===name));for(const s of document.querySelectorAll('[data-section]'))s.classList.toggle('active',s.dataset.section===name)}\n for(const b of document.querySelectorAll('[data-tab]'))b.addEventListener('click',()=>tab(b.dataset.tab));\n $('fullName').addEventListener('input',preview);\n async function saveProfile(){\n   if(!state.loaded||state.deleted)throw Error('Sign in before editing your profile');\n   const body={full_name:$('fullName').value.trim(),theme:state.theme,avatar_data:state.avatar};\n   const r=await call(api+'/profile','PUT',body);state.profile={...state.profile,...r};note('Profile and appearance saved');\n }\n $('profileForm').addEventListener('submit',async e=>{e.preventDefault();try{await saveProfile()}catch(err){note(err.message,true)}});\n $('saveTheme').addEventListener('click',async()=>{try{await saveProfile()}catch(e){note(e.message,true)}});\n for(const b of document.querySelectorAll('[data-theme-choice]'))b.addEventListener('click',()=>theme(b.dataset.themeChoice));\n $('clearAvatar').addEventListener('click',()=>{state.avatar=null;$('avatarFile').value='';preview();note('Avatar removed locally. Save profile to persist.')});\n $('avatarFile').addEventListener('change',async e=>{\n   const file=e.target.files?.[0];if(!file)return;\n   if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>4000000){note('Choose a PNG, JPEG or WebP smaller than 4 MB',true);return}\n   try{\n    const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=96;canvas.height=96;\n    const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas unavailable');\n    const scale=Math.min(96/bitmap.width,96/bitmap.height),w=bitmap.width*scale,h=bitmap.height*scale;\n    ctx.clearRect(0,0,96,96);ctx.drawImage(bitmap,(96-w)/2,(96-h)/2,w,h);bitmap.close();\n    const uri=canvas.toDataURL('image/webp',.7);\n    if(!uri.startsWith('data:image/webp;')||uri.length>33000)throw Error('Resized image is too large');\n    state.avatar=uri;preview();note('Avatar prepared. Save profile to persist.');\n   }catch(err){note(String(err.message||err),true)}\n });\n $('keyForm').addEventListener('submit',async e=>{\n  e.preventDefault();try{\n   const data=await call(api+'/keys','POST',{label:$('keyLabel').value.trim(),kind:$('keyKind').value,expires_days:Number($('keyExpiry').value)});\n   $('secretOutput').textContent=data.token;$('secretPanel').hidden=false;$('keyLabel').value='';\n   note('Key created and shown once. Copy it before dismissing.');await load();\n  }catch(err){note(err.message,true)}\n });\n $('copySecret').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('secretOutput').textContent);note('Credential copied to clipboard')}catch(e){note('Clipboard not available: manually select the displayed key.',true)}});\n $('dismissSecret').addEventListener('click',()=>{$('secretOutput').textContent='';$('secretPanel').hidden=true});\n $('sshForm').addEventListener('submit',async e=>{e.preventDefault();try{const data=await call(api+'/ssh','POST',{label:$('sshLabel').value.trim(),public_key:$('sshPublic').value.trim()});$('sshLabel').value='';$('sshPublic').value='';note('SSH public key stored · '+data.fingerprint);await load()}catch(err){note(err.message,true)}});\n $('deleteForm').addEventListener('submit',async e=>{\n  e.preventDefault();if($('deleteConfirm').value!=='DELETE MY SHARDS ACCOUNT'){note('Type the exact deletion confirmation phrase',true);return}\n  if(!confirm('Final confirmation: permanently delete local profile, revoke issued keys and disable owned agents? Cloudflare identity and audit history are not removed.'))return;\n  try{const r=await call(api,'DELETE',{confirm:'DELETE MY SHARDS ACCOUNT'});state.deleted=true;for(const form of document.querySelectorAll('form'))for(const item of form.querySelectorAll('input,button,select,textarea'))item.disabled=true;note('Shards-local account deleted. Cloudflare identity and historical organisation audit remain.')}catch(err){note(err.message,true)}\n });\n load();\n})();";
