// Operator workspace reuses the existing tenant, inbox and audit schema.
// A human operator is a distinct non-token principal, never an impersonated AI agent.
const operatorPrincipalId=subHash=>'operator_'+subHash.slice(0,32);
async function workspaceSnapshot(env,operatorSub,requestedAgentId=null){
  const principal=operatorPrincipalId(await digest(operatorSub));
  const directory=await env.EDGE_DB.prepare("SELECT id,name,client,created_at FROM agents WHERE tenant_id='shards-internal' AND disabled_at IS NULL ORDER BY created_at DESC LIMIT 80").all();
  const agents=directory.results||[];
  const focus=requestedAgentId||agents.find(a=>a.client!=='operator-ui')?.id||null;
  if(requestedAgentId&&!agents.some(a=>a.id===requestedAgentId&&a.client!=='operator-ui'))return null;
  if(!focus)return {operator_id:principal,focus_id:null,agents,messages:[],tasks:[],limits:{messages:200,tasks:80,refresh:'polling',presence:'unverified',tenant:'shards-internal'}};
  const [messages,tasks]=await Promise.all([
    env.EDGE_DB.prepare("SELECT m.id,m.sender_id,m.recipient_id,m.body,m.created_at,m.read_at,s.name AS sender_name,r.name AS recipient_name FROM agent_messages m JOIN agents s ON m.sender_id=s.id JOIN agents r ON m.recipient_id=r.id WHERE m.tenant_id='shards-internal' AND (m.sender_id=? OR m.recipient_id=?) ORDER BY m.created_at DESC LIMIT 200").bind(focus,focus).all(),
    env.EDGE_DB.prepare("SELECT t.id,t.creator_id,t.assignee_id,t.title,t.state,t.created_at,t.claimed_at,t.completed_at,a.name AS assignee_name FROM agent_tasks t JOIN agents a ON t.assignee_id=a.id WHERE t.tenant_id='shards-internal' AND (t.creator_id=? OR t.assignee_id=?) ORDER BY t.created_at DESC LIMIT 80").bind(focus,focus).all()
  ]);
  return {operator_id:principal,focus_id:focus,agents,messages:messages.results||[],tasks:tasks.results||[],limits:{messages:200,tasks:80,refresh:'polling',presence:'unverified',tenant:'shards-internal'}};
}
async function readWorkspaceJSON(request){
  const limit=16000;
  const stated=Number(request.headers.get('content-length'));
  if(Number.isFinite(stated)&&stated>limit)throw Error('Request too large');
  if(!request.body)throw Error('Missing body');
  const reader=request.body.getReader(),parts=[];let size=0;
  try{
    while(true){
      const {done,value}=await reader.read();if(done)break;
      size+=value.byteLength;if(size>limit){await reader.cancel().catch(()=>{});throw Error('Request too large')}
      parts.push(value);
    }
  }finally{reader.releaseLock()}
  const data=new Uint8Array(size);let at=0;
  for(const part of parts){data.set(part,at);at+=part.byteLength}
  return JSON.parse(decoder.decode(data));
}
async function operatorSendMessage(env,sub,b){
  if(!b||typeof b!=='object'||Array.isArray(b)||Object.keys(b).some(k=>!['recipient_agent_id','body','request_id'].includes(k)))return pub({error:'Invalid message request'},400);
  const recipient=b.recipient_agent_id,body=typeof b.body==='string'?b.body.trim():null;
  if(typeof recipient!=='string'||!idPattern.test(recipient)||!body||body.length>2000||!reqId(b.request_id))return pub({error:'Invalid recipient, message or idempotency key'},400);
  const hash=await digest(sub),operatorId=operatorPrincipalId(hash);
  if(recipient===operatorId)return pub({error:'Select a separate enrolled agent'},400);
  // A committed retry is reportable even if the recipient was later revoked.
  // Do not treat a replay as permission to create a new message after revocation.
  const committed=await env.EDGE_DB.prepare("SELECT id,body,recipient_id FROM agent_messages WHERE tenant_id='shards-internal' AND sender_id=? AND request_key=?").bind(operatorId,b.request_id).first();
  if(committed){
    const principal=await env.EDGE_DB.prepare("SELECT disabled_at,client FROM agents WHERE id=? AND tenant_id='shards-internal'").bind(operatorId).first();
    if(!principal||principal.disabled_at||principal.client!=='operator-ui')return pub({error:'Operator principal is disabled or invalid'},403);
    if(committed.recipient_id!==recipient||committed.body!==body)return pub({error:'Idempotency key reused for a different message'},409);
    return pub({id:committed.id,stored:true,idempotent:true},200);
  }
  const target=await env.EDGE_DB.prepare("SELECT id,scopes FROM agents WHERE id=? AND tenant_id='shards-internal' AND disabled_at IS NULL AND client!='operator-ui'").bind(recipient).first();
  if(!target)return pub({error:'Recipient is not an enrolled active agent'},404);
  let scopes;try{scopes=JSON.parse(target.scopes)}catch(e){scopes=[]}
  if(!Array.isArray(scopes)||!scopes.includes('message:read'))return pub({error:'Recipient lacks message:read scope; re-enrol with inbox permission'},409);
  const createdAt=new Date().toISOString(),name='Operator_'+hash.slice(0,40);
  await env.EDGE_DB.prepare("INSERT OR IGNORE INTO agents(id,tenant_id,name,client,scopes,created_by,created_at) VALUES(?,'shards-internal',?,'operator-ui','[]',?,?)").bind(operatorId,name,hash,createdAt).run();
  const principal=await env.EDGE_DB.prepare("SELECT disabled_at,client FROM agents WHERE id=? AND tenant_id='shards-internal'").bind(operatorId).first();
  if(!principal||principal.disabled_at||principal.client!=='operator-ui')return pub({error:'Operator principal is disabled or invalid'},403);
  const row=await env.EDGE_DB.prepare("SELECT id,body,recipient_id FROM agent_messages WHERE tenant_id='shards-internal' AND sender_id=? AND request_key=?").bind(operatorId,b.request_id).first();
  if(row){
    if(row.recipient_id!==recipient||row.body!==body)return pub({error:'Idempotency key reused for a different message'},409);
    return pub({id:row.id,stored:true,idempotent:true},200);
  }
  const id=crypto.randomUUID();
  // D1 batch is transactional: the new message and its audit receipt commit or roll back together.
  await env.EDGE_DB.batch([
    env.EDGE_DB.prepare("INSERT OR IGNORE INTO agent_messages(id,tenant_id,sender_id,recipient_id,body,created_at,request_key) SELECT ?,'shards-internal',s.id,r.id,?,?,? FROM agents s JOIN agents r ON r.id=? AND r.tenant_id='shards-internal' AND r.disabled_at IS NULL AND r.client!='operator-ui' AND EXISTS(SELECT 1 FROM json_each(r.scopes) WHERE value='message:read') WHERE s.id=? AND s.tenant_id='shards-internal' AND s.disabled_at IS NULL AND s.client='operator-ui'").bind(id,body,createdAt,b.request_id,recipient,operatorId),
    env.EDGE_DB.prepare("INSERT INTO audit_events(id,tenant_id,agent_id,action,object_id,status,created_at) SELECT ?,'shards-internal',?,'operator_message_send',?,'stored',? FROM agent_messages WHERE id=? AND tenant_id='shards-internal'").bind(crypto.randomUUID(),operatorId,id,createdAt,id)
  ]);
  const saved=await env.EDGE_DB.prepare("SELECT id,body,recipient_id FROM agent_messages WHERE tenant_id='shards-internal' AND sender_id=? AND request_key=?").bind(operatorId,b.request_id).first();
  if(!saved)return pub({error:'Sender or recipient unavailable; message not stored'},403);
  if(saved.recipient_id!==recipient||saved.body!==body)return pub({error:'Concurrent idempotency conflict'},409);
  return pub({id:saved.id,stored:true,idempotent:saved.id!==id},saved.id===id?201:200);
}

